//! M3.2 cross-version state translation tables (1.21.1 <-> 26.3).
//!
//! Generated by `scripts/gen-remap-tables.py` from pinned mcmeta snapshots
//! (see `data/remap-manifest.tsv`). The Java `dev.cim.bridge.StateMapper`
//! loads the SAME files from the bootstrap jar — a unit test below asserts
//! byte equality between the two embedded copies so the tables can never
//! drift apart.
//!
//! Measured drift 1.21.1 -> 26.3 (release, pinned):
//! - blocks 1060 -> 1286: one rename (chain -> iron_chain), 227 additions,
//!   one value-set drift (note_block `instrument` gains trumpet* values);
//! - entity_type: boat/chest_boat split per wood (default oak), thrown
//!   potion entity became splash_potion/lingering_potion;
//! - attributes flattened: `generic.X` / `player.X` -> `X`;
//! - fluid registry unchanged (5 -> 5).
//!
//! Policy: translation is a pure string function; unknown states pass
//! through untouched; modded namespaces never enter the tables.

use std::collections::HashMap;
use std::sync::OnceLock;

/// Blockstate drift rows (generated, byte-shared with the Java side).
const BLOCKSTATE_DRIFT: &str = include_str!("../data/blockstate-drift.tsv");
/// Registry key drift rows (generated, byte-shared with the Java side).
const REGISTRY_DRIFT: &str = include_str!("../data/registry-drift.tsv");

/// Property drift for one block between the two versions.
#[derive(Debug, Clone)]
struct PropDrift {
    kind: PropKind,
    old_default: Option<String>,
    new_default: Option<String>,
    /// old value -> new value (None = no counterpart, use default)
    map: HashMap<String, String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum PropKind {
    Removed,
    Added,
    Changed,
}

/// Drift of one block's property set (plus optional rename).
#[derive(Debug, Default, Clone)]
struct BlockDrift {
    renamed_to: Option<String>,
    props: HashMap<String, PropDrift>,
}

/// Loaded translation tables (immutable after init).
#[derive(Debug, Default)]
pub struct DriftTables {
    blocks: HashMap<String, BlockDrift>,
    block_rename_inverse: HashMap<String, String>,
    /// registry -> old bare key -> new bare key
    registry_pairs: HashMap<String, HashMap<String, String>>,
    /// registry -> new bare key -> old bare key
    registry_pairs_inverse: HashMap<String, HashMap<String, String>>,
    /// registry keys with no 26.3 counterpart (no mapping possible)
    removed_keys: usize,
}

impl DriftTables {
    /// Parse the generated TSVs (panics on a malformed generated table —
    /// that is a build error, not a runtime condition).
    pub fn load() -> Self {
        let mut t = Self::default();
        t.parse_blockstate(BLOCKSTATE_DRIFT);
        t.removed_keys = t.parse_registry(REGISTRY_DRIFT);
        t
    }

    fn parse_blockstate(&mut self, data: &str) {
        for line in data.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let Some((key, json)) = line.split_once('\t') else {
                continue;
            };
            let bare = bare_name(key);
            let drift = self.blocks.entry(bare.to_string()).or_default();
            if let Some(rest) = json.split("\"renamedTo\":\"").nth(1) {
                if let Some(end) = rest.find('"') {
                    let renamed = &rest[..end];
                    drift.renamed_to = Some(renamed.to_string());
                    self.block_rename_inverse
                        .insert(renamed.to_string(), bare.to_string());
                }
            }
            for (marker, kind) in [
                ("\"removed\":[", PropKind::Removed),
                ("\"added\":[", PropKind::Added),
                ("\"changed\":[", PropKind::Changed),
            ] {
                let Some(rest) = json.split(marker).nth(1) else {
                    continue;
                };
                for obj in brace_objects(rest) {
                    let Some(name) = json_str_field(obj, "name") else {
                        continue;
                    };
                    let map = if kind == PropKind::Changed {
                        json_map_field(obj, "map")
                    } else {
                        HashMap::new()
                    };
                    drift.props.insert(
                        name,
                        PropDrift {
                            kind,
                            old_default: json_str_field(obj, "oldDefault"),
                            new_default: json_str_field(obj, "newDefault"),
                            map,
                        },
                    );
                }
            }
        }
    }

    fn parse_registry(&mut self, data: &str) -> usize {
        let mut removed = 0;
        for line in data.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let cols: Vec<&str> = line.split('\t').collect();
            let Some((registry, old_key)) = (cols.first().zip(cols.get(1))).map(|(r, o)| (*r, *o))
            else {
                continue;
            };
            let new_key = cols.get(2).copied().unwrap_or("");
            if new_key.is_empty() {
                removed += 1;
                continue;
            }
            self.registry_pairs
                .entry(registry.to_string())
                .or_default()
                .insert(bare_name(old_key).to_string(), new_key.to_string());
            self.registry_pairs_inverse
                .entry(registry.to_string())
                .or_default()
                .insert(new_key.to_string(), bare_name(old_key).to_string());
        }
        removed
    }

    /// 1.21.1 blockstate string -> 26.3 kernel string (pure function).
    pub fn layer_to_kernel_state(&self, state: &str) -> String {
        self.translate_state(state, true)
    }

    /// 26.3 kernel blockstate string -> 1.21.1 layer string (pure function).
    pub fn kernel_to_layer_state(&self, state: &str) -> String {
        self.translate_state(state, false)
    }

    fn translate_state(&self, state: &str, forward: bool) -> String {
        let Some((key, props_part)) = split_state(state) else {
            return state.to_string();
        };
        if !key.starts_with("minecraft:") {
            return state.to_string();
        }
        let bare = bare_name(key);
        let (drift, target_bare): (&BlockDrift, &str) = if forward {
            match self.blocks.get(bare) {
                Some(d) => (d, d.renamed_to.as_deref().unwrap_or(bare)),
                None => {
                    // pure rename (chain -> iron_chain) lives in the registry table
                    return match self.registry_pair("block", bare) {
                        Some(renamed) => rebuild_state(renamed, props_part),
                        None => state.to_string(),
                    };
                }
            }
        } else {
            let old_bare: &str = self
                .block_rename_inverse
                .get(bare)
                .map_or(bare, String::as_str);
            match self.blocks.get(old_bare) {
                Some(d) => (d, old_bare),
                None => {
                    return match self.registry_pair_inverse("block", bare) {
                        Some(old) => rebuild_state(old, props_part),
                        None => state.to_string(),
                    };
                }
            }
        };
        let Some(props) = props_part else {
            return format!("minecraft:{target_bare}");
        };
        let mut out: Vec<(String, String)> = Vec::with_capacity(props.len());
        for (prop, value) in props {
            let Some(pd) = drift.props.get(prop) else {
                out.push((prop.to_string(), value.to_string()));
                continue;
            };
            match (forward, pd.kind) {
                (true, PropKind::Removed) => {} // property gone in 26.3
                (true, PropKind::Changed) => {
                    let nv = pd
                        .map
                        .get(value)
                        .filter(|v| !v.is_empty())
                        .or(pd.new_default.as_ref());
                    if let Some(nv) = nv {
                        out.push((prop.to_string(), nv.clone()));
                    }
                }
                (true, PropKind::Added) => out.push((prop.to_string(), value.to_string())),
                (false, PropKind::Added) => {} // property did not exist in 1.21.1
                (false, PropKind::Changed) => {
                    let ov = pd
                        .map
                        .iter()
                        .find(|(_, nv)| !nv.is_empty() && nv.as_str() == value)
                        .map(|(ov, _)| ov.clone())
                        .or_else(|| pd.old_default.clone());
                    if let Some(ov) = ov {
                        out.push((prop.to_string(), ov));
                    }
                }
                (false, PropKind::Removed) => out.push((prop.to_string(), value.to_string())),
            }
        }
        format_state(&format!("minecraft:{target_bare}"), &out)
    }

    /// Registry key 1.21.1 -> 26.3 ("minecraft:boat" -> "minecraft:oak_boat").
    pub fn layer_to_kernel_key(&self, registry: &str, full_key: &str) -> String {
        self.translate_key(&self.registry_pairs, registry, full_key)
    }

    /// Registry key 26.3 -> 1.21.1 ("minecraft:max_health" -> "minecraft:generic.max_health").
    pub fn kernel_to_layer_key(&self, registry: &str, full_key: &str) -> String {
        self.translate_key(&self.registry_pairs_inverse, registry, full_key)
    }

    fn translate_key(
        &self,
        side: &HashMap<String, HashMap<String, String>>,
        registry: &str,
        full_key: &str,
    ) -> String {
        let Some(table) = side.get(registry) else {
            return full_key.to_string();
        };
        if !full_key.starts_with("minecraft:") {
            return full_key.to_string();
        }
        match table.get(bare_name(full_key)) {
            Some(mapped) => format!("minecraft:{mapped}"),
            None => full_key.to_string(),
        }
    }

    fn registry_pair(&self, registry: &str, bare_old: &str) -> Option<&str> {
        self.registry_pairs
            .get(registry)?
            .get(bare_old)
            .map(String::as_str)
    }

    fn registry_pair_inverse(&self, registry: &str, bare_new: &str) -> Option<&str> {
        self.registry_pairs_inverse
            .get(registry)?
            .get(bare_new)
            .map(String::as_str)
    }

    /// Blocks with any drift (incl. renames).
    pub fn block_drift_count(&self) -> usize {
        self.blocks.len()
    }

    /// Total paired registry keys across all registries.
    pub fn registry_pair_count(&self) -> usize {
        self.registry_pairs.values().map(HashMap::len).sum()
    }

    /// Registry keys with no 26.3 counterpart.
    pub fn removed_key_count(&self) -> usize {
        self.removed_keys
    }
}

/// Process-wide shared tables (tiny; init once).
pub fn tables() -> &'static DriftTables {
    static TABLES: OnceLock<DriftTables> = OnceLock::new();
    TABLES.get_or_init(DriftTables::load)
}

// ---- tiny string helpers (the generated rows are machine-shaped) ----------

fn bare_name(key: &str) -> &str {
    match key.split_once(':') {
        Some((_, b)) => b,
        None => key,
    }
}

type ParsedProps<'a> = Option<Vec<(&'a str, &'a str)>>;

fn split_state(state: &str) -> Option<(&str, ParsedProps<'_>)> {
    let (key, props) = match state.split_once('[') {
        Some((k, rest)) => {
            let props = rest.strip_suffix(']')?;
            let parsed: Vec<(&str, &str)> = props
                .split(',')
                .filter(|p| !p.is_empty())
                .filter_map(|p| p.split_once('='))
                .collect();
            (k, Some(parsed))
        }
        None => (state, None),
    };
    Some((key, props))
}

fn rebuild_state(new_key: &str, props: ParsedProps<'_>) -> String {
    match props {
        None => format!("minecraft:{new_key}"),
        Some(props) => format_state(&format!("minecraft:{new_key}"), &props),
    }
}

fn format_state<K: AsRef<str>, V: AsRef<str>>(key: &str, props: &[(K, V)]) -> String {
    if props.is_empty() {
        return key.to_string();
    }
    let mut out = String::with_capacity(key.len() + 2 + props.len() * 12);
    out.push_str(key);
    out.push('[');
    for (i, (k, v)) in props.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(k.as_ref());
        out.push('=');
        out.push_str(v.as_ref());
    }
    out.push(']');
    out
}

/// Iterate brace-balanced top-level `{...}` objects of a minified array body.
fn brace_objects(data: &str) -> impl Iterator<Item = &str> {
    let mut objs = Vec::new();
    let mut depth = 0usize;
    let mut start = 0usize;
    for (i, c) in data.char_indices() {
        match c {
            '{' => {
                if depth == 0 {
                    start = i + 1;
                }
                depth += 1;
            }
            '}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    objs.push(&data[start..i]);
                }
            }
            _ => {}
        }
    }
    objs.into_iter()
}

fn json_str_field(obj: &str, field: &str) -> Option<String> {
    let needle = format!("\"{field}\":\"");
    let at = obj.find(&needle)? + needle.len();
    let end = obj[at..].find('"')? + at;
    Some(obj[at..end].to_string())
}

fn json_map_field(obj: &str, field: &str) -> HashMap<String, String> {
    let mut out = HashMap::new();
    let needle = format!("\"{field}\":{{");
    let Some(at) = obj.find(&needle) else {
        return out;
    };
    let from = at + needle.len();
    let Some(end) = obj[from..].find('}') else {
        return out;
    };
    for pair in obj[from..from + end].split(',') {
        let Some((k, v)) = pair.split_once(':') else {
            continue;
        };
        let k = k.trim().trim_matches('"');
        let v = v.trim().trim_matches('"');
        if !k.is_empty() {
            out.insert(k.to_string(), v.to_string());
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The Java side's copies (byte-equality asserted below).
    const JAVA_BLOCKSTATE_DRIFT: &str =
        include_str!("../../../java/cim-bootstrap/src/main/resources/cim/blockstate-drift.tsv");
    const JAVA_REGISTRY_DRIFT: &str =
        include_str!("../../../java/cim-bootstrap/src/main/resources/cim/registry-drift.tsv");

    #[test]
    fn tables_match_the_java_side_byte_for_byte() {
        assert_eq!(BLOCKSTATE_DRIFT, JAVA_BLOCKSTATE_DRIFT);
        assert_eq!(REGISTRY_DRIFT, JAVA_REGISTRY_DRIFT);
    }

    #[test]
    fn table_census_matches_generation() {
        let t = tables();
        assert_eq!(t.block_drift_count(), 1, "only note_block has prop drift");
        assert_eq!(t.registry_pair_count(), 36, "31 attr + 5 explicit pairs");
        assert_eq!(t.removed_key_count(), 18);
    }

    #[test]
    fn note_block_identity_and_reverse() {
        let t = tables();
        assert_eq!(
            t.layer_to_kernel_state("minecraft:note_block[instrument=harp]"),
            "minecraft:note_block[instrument=harp]"
        );
        assert_eq!(
            t.kernel_to_layer_state("minecraft:note_block[instrument=trumpet_oxidized]"),
            "minecraft:note_block[instrument=harp]"
        );
        // a 1.21.1 value maps through the identity map
        assert_eq!(
            t.layer_to_kernel_state("minecraft:note_block[instrument=zombie]"),
            "minecraft:note_block[instrument=zombie]"
        );
    }

    #[test]
    fn chain_rename_roundtrip() {
        let t = tables();
        assert_eq!(
            t.layer_to_kernel_state("minecraft:chain[axis=y,waterlogged=true]"),
            "minecraft:iron_chain[axis=y,waterlogged=true]"
        );
        assert_eq!(
            t.kernel_to_layer_state("minecraft:iron_chain[axis=x]"),
            "minecraft:chain[axis=x]"
        );
        assert_eq!(
            t.layer_to_kernel_state("minecraft:chain"),
            "minecraft:iron_chain"
        );
        assert_eq!(
            t.kernel_to_layer_state("minecraft:iron_chain"),
            "minecraft:chain"
        );
    }

    #[test]
    fn registry_key_translation() {
        let t = tables();
        assert_eq!(
            t.layer_to_kernel_key("entity_type", "minecraft:boat"),
            "minecraft:oak_boat"
        );
        assert_eq!(
            t.layer_to_kernel_key("entity_type", "minecraft:chest_boat"),
            "minecraft:oak_chest_boat"
        );
        assert_eq!(
            t.layer_to_kernel_key("entity_type", "minecraft:potion"),
            "minecraft:splash_potion"
        );
        assert_eq!(
            t.layer_to_kernel_key("attribute", "minecraft:generic.max_health"),
            "minecraft:max_health"
        );
        assert_eq!(
            t.layer_to_kernel_key("attribute", "minecraft:player.block_break_speed"),
            "minecraft:block_break_speed"
        );
        assert_eq!(
            t.kernel_to_layer_key("attribute", "minecraft:sweeping_damage_ratio"),
            "minecraft:player.sweeping_damage_ratio"
        );
        assert_eq!(
            t.kernel_to_layer_key("entity_type", "minecraft:oak_chest_boat"),
            "minecraft:chest_boat"
        );
    }

    #[test]
    fn unknown_and_modded_pass_through() {
        let t = tables();
        assert_eq!(
            t.layer_to_kernel_state("minecraft:stone"),
            "minecraft:stone"
        );
        assert_eq!(t.kernel_to_layer_state("minecraft:dirt"), "minecraft:dirt");
        assert_eq!(
            t.layer_to_kernel_state("cimtest:test_block[foo=bar]"),
            "cimtest:test_block[foo=bar]"
        );
        assert_eq!(
            t.layer_to_kernel_key("entity_type", "cimtest:test_entity"),
            "cimtest:test_entity"
        );
        assert_eq!(
            t.layer_to_kernel_key("unknown_registry", "minecraft:x"),
            "minecraft:x"
        );
    }

    #[test]
    fn removed_keys_have_no_mapping() {
        let t = tables();
        // bed block entity does not exist in 26.3 — nothing to map to
        assert_eq!(
            t.layer_to_kernel_key("block_entity_type", "minecraft:bed"),
            "minecraft:bed"
        );
        assert_eq!(
            t.layer_to_kernel_key("data_component_type", "minecraft:hide_tooltip"),
            "minecraft:hide_tooltip"
        );
    }
}
